import { chromium } from 'playwright-core';
import fs from 'node:fs';
import path from 'node:path';

const OUT = process.argv[2];
fs.mkdirSync(OUT, { recursive: true });
const exe = fs.readdirSync(path.join(process.env.HOME, 'Library/Caches/ms-playwright'))
  .filter((d) => d.startsWith('chromium-'))
  .map((d) => path.join(process.env.HOME, 'Library/Caches/ms-playwright', d, 'chrome-mac-arm64'))[0];
const app = fs.readdirSync(exe).find((f) => f.endsWith('.app'));
const executablePath = path.join(exe, app, 'Contents/MacOS', app.replace('.app', ''));

const browser = await chromium.launch({ executablePath });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function openReader(page, url) {
  await page.goto(url);
  await page.waitForSelector('[data-test="conversation-row-conv-01"]');
  await page.keyboard.press('Enter');
  await page.waitForSelector('[data-test="reader"]');
  await sleep(400);
}

async function shot(page, name) {
  await page.screenshot({ path: path.join(OUT, name) });
  console.log('saved', name);
}

// ---------- stills (2x) ----------
{
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 2 });
  const page = await ctx.newPage();

  await openReader(page, 'http://localhost:5221/');
  await shot(page, '01-before-1280.png');

  await openReader(page, 'http://localhost:5220/');
  await shot(page, '02-after-1280.png');

  // Details open on the active message
  await page.click('[data-test="message-details-summary-conv-01-m3"]');
  await sleep(200);
  await shot(page, '03-after-details-open.png');
  await page.keyboard.press('Escape');
  await sleep(200);

  // Earlier message expanded (no reply glyph on it)
  await page.click('[data-test="message-toggle-conv-01-m1"]');
  await sleep(250);
  await shot(page, '04-after-earlier-message-active.png');

  // Keyboard focus on the reply glyph
  await openReader(page, 'http://localhost:5220/');
  await page.focus('[data-test="message-reply-conv-01-m3"]');
  await sleep(200);
  await shot(page, '05-after-reply-glyph-focused.png');

  // Header icon focus ring (keyboard)
  await page.focus('[data-test="reader-archive-toggle"]');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Tab');
  await sleep(200);
  await shot(page, '06-after-header-icon-focused.png');

  // Monospace fallback: stage a quoted body in the DOM (class + text only) to show the CSS
  await openReader(page, 'http://localhost:5220/');
  await page.evaluate(() => {
    const body = document.querySelector('[data-test="message-body"]:not([hidden])');
    body.textContent = 'On Thu, Ada wrote:\n> Can we move the sync to Friday?\n> The table below is aligned:\n\n  item     qty\n  widgets   12\n  gadgets    7\n\nFriday works.';
    body.classList.add('message-body-mono');
  });
  await sleep(150);
  await shot(page, '07-after-mono-fallback-staged.png');

  // Prose paragraph
  await openReader(page, 'http://localhost:5220/');
  await page.evaluate(() => {
    const body = document.querySelector('[data-test="message-body"]:not([hidden])');
    body.textContent = 'Thanks for the quick turnaround. I looked through the proposal and the main open question is how we sequence the rollout across the two teams, since the dependency on the evaluation pipeline lands later than the agent platform work. If we can agree on the order this week, I can draft the plan and share it before the next sync so we have time to adjust.\n\nHappy to talk it through whenever suits you.';
  });
  await sleep(150);
  await shot(page, '08-after-long-prose-staged.png');
  await ctx.close();
}

// ---------- 1030 ----------
{
  const ctx = await browser.newContext({ viewport: { width: 1030, height: 800 }, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  await openReader(page, 'http://localhost:5220/');
  await shot(page, '09-after-1030.png');
  await ctx.close();
}

// ---------- video: before and after flows ----------
async function flow(url, name, after) {
  const ctx = await browser.newContext({
    viewport: { width: 1280, height: 800 },
    recordVideo: { dir: path.join(OUT, 'video-tmp'), size: { width: 1280, height: 800 } },
  });
  const page = await ctx.newPage();
  await page.goto(url);
  await page.waitForSelector('[data-test="conversation-row-conv-01"]');
  await sleep(1200);
  await page.keyboard.press('Enter'); // open
  await sleep(1600);
  if (after) {
    await page.click('[data-test="message-toggle-conv-01-m1"]'); // expand earlier message
    await sleep(1400);
    await page.click('[data-test="message-details-summary-conv-01-m1"]'); // details
    await sleep(1600);
    await page.keyboard.press('Escape');
    await sleep(900);
  }
  await page.keyboard.press('j'); // next conversation
  await sleep(1500);
  await page.keyboard.press('k'); // previous
  await sleep(1500);
  await page.keyboard.press('e'); // mark done
  await sleep(1800);
  await page.keyboard.press('Escape');
  await sleep(1200);
  const v = page.video();
  await ctx.close();
  const p = await v.path();
  fs.renameSync(p, path.join(OUT, name));
  console.log('video', name);
}
await flow('http://localhost:5221/', 'flow-before.webm', false);
await flow('http://localhost:5220/', 'flow-after.webm', true);
fs.rmSync(path.join(OUT, 'video-tmp'), { recursive: true, force: true });
await browser.close();

